// 聲音來自學生的 Pure Data patch(shared/synth.pd),這支只負責「什麼時候發聲」。
// PD 是框架注入的第三個參數;沒有 .pd 或編譯失敗時會是 null,所以一律先檢查。
const PADS = [];
if (PD) GameAPI.log('patch 入口:', PD.names.in.join(', '));

GameAPI.onInput((pid, key, down, player) => {
  if (!down) return;
  // 每個按鍵對到一個音階度數,玩家編號決定八度 —— 一人一個音域,聽得出誰在按
  const idx = [...GameAPI.players.keys()].indexOf(pid);
  const degree = { btn1: 0, btn2: 2, btn3: 4, btn4: 5, btn5: 7, btn6: 9, btn7: 11, btn8: 12 }[key] ?? 0;
  const semi = 48 + idx * 12 + degree;
  if (PD) PD.send('hit', [semi]);          // → patch 裡的 [s hit] → [r hit]
  PADS.push({ x: Math.random() * GameAPI.width, y: Math.random() * GameAPI.height,
              r: 10, c: (player && player.color) || '#8cf', t: 0 });
});

GameAPI.update(() => {
  const g = GameAPI.ctx;
  g.fillStyle = '#0b0b16';
  g.fillRect(0, 0, GameAPI.width, GameAPI.height);
  g.font = '28px sans-serif'; g.fillStyle = '#667';
  g.fillText(PD ? '按手機上的鈕 — 聲音來自 Pure Data patch' : '沒有載到聲音 patch(看 log)', 60, 70);
  for (let i = PADS.length - 1; i >= 0; i--) {
    const p = PADS[i];
    p.t += 1; p.r += 6;
    g.globalAlpha = Math.max(0, 1 - p.t / 45);
    g.strokeStyle = p.c; g.lineWidth = 4;
    g.beginPath(); g.arc(p.x, p.y, p.r, 0, Math.PI * 2); g.stroke();
    g.globalAlpha = 1;
    if (p.t > 45) PADS.splice(i, 1);
  }
});
